const phase=(id,name,elements,range,kind,direction,reference,condition,refs,example)=>({id,name,elements,range,kind,direction,reference,condition,refs,example});
export function temperatureSettings(s){if(!s.temperatureGuide||s.temperatureGuide.version!==1)s.temperatureGuide={version:1,liquidus:1500,superheatLow:20,superheatHigh:35,transferDrop:20,probeT:1600,pressure:66,h2Percent:10,fH:1,temps:{},filter:'all'};const t=s.temperatureGuide;t.temps??={};return t;}
