 VD:[phase('h','真空保压 · 脱氢',['H'],[1560,1640],'screen','固定pH₂和fH时升温提高H平衡溶解度；传质改善不等于热力学更有利。','T04的1600°C是参考点，不是优化结果。','低pH₂、足够循环及有效处理时间关键；总真空压力不等于氢分压。',['T04'],1600),...(context.desulf?[phase('s','渣钢协同 · 脱硫',['S'],[1580,1650],'screen','脱硫由还原渣、氧活度与传质控制，真空本身不直接去S。','温区沿用LF教学初筛，不是VD实验最优窗。','仅在已脱氧且存在有效脱硫渣时讨论；原模型的协同条件仍适用。',['T02','T04'],1600)]:[])],
 RH:[phase('vac','循环脱气 / 低碳钢脱碳',['H','C','O'],[1580,1600],'study','降低pCO推动[C]+[O]→CO；脱氢仍需区分温度平衡与传质。','T05为IF/ULC工业温度案例。','高碳轴承钢或不锈钢不能照抄低碳IF脱碳任务。'+steelNote,['T05','T04'],1600),...(context.powderEnabled?[phase('powder','可选上升管喷粉',['S'],null,'unset','取决于粉末配方、有效渣与氧活度，不能仅凭温度决定脱硫。','原喷粉输运论文不足以给化学反应最佳温区。','需补充具体粉料、渣成分与平衡计算；本处不把脱硫粉当作补热粉。',['T02'],1600)]:[])],
