 VOD:[phase('blow','真空吹氧脱碳',['C','Cr'],null,'unset','降低pCO可在较低碳活度下继续脱碳；温度、活度和真空度需共同求解。','T09仅核实摘要，未据此填写数值最佳窗。','1600°C仅是可修改的计划示例；需要对应钢种的完整工艺数据。',['T09'],1600),phase('reduction','还原 / 脱气 / 离站',['Cr','H','O'],null,'unset','还原与脱气的约束不同；低碳不锈钢还需控制回碳、再氧化与铬收得。','温度范围待钢种与渣系标定。','不能用316L的AOD摘要替代VOD温度验证。',['T09','T04'],1600)],
